(** Projection keeps live sets and memory access records out of the membership computation. *)
Definition table_labels : list (string * list name) := Eval lazy in
  [("__GI__IO_flush_all", app (map fst fn___GI__IO_flush_all.block_src) (app (map fst fn___GI__IO_flush_all.live_in) (app (map fst fn___GI__IO_flush_all.live_out) (app (map fst fn___GI__IO_flush_all.footprint) (fn___GI__IO_flush_all.loop_heads)))))].

